// scripting/scripts/Calendar Timeline Scripting/bridge-auto.ts
async function autoSynchronize(options) {
  try {
    if (!Storage.get("test-scope-consent") || !configuration()) return { state: "unpaired" };
    const now = Date.now(), attempt = Storage.get("bridge-auto-attempt") ?? 0;
    if (!options.force && now - attempt < 6e4) return { state: "throttled" };
    if (!Storage.set("bridge-auto-attempt", now)) throw Error("Falha ao guardar a tentativa autom\xE1tica.");
    const report = await synchronize({ budgetMS: options.budgetMS ?? 1e4, origin: options.origin });
    const originLabel = { "widget": "execu\xE7\xE3o do widget", "app-open": "abertura do projeto", "widget-touch": "toque na timeline", "day-touch": "sele\xE7\xE3o de dia" }[options.origin] ?? options.origin;
    const result = { state: "success", origin: options.origin, at: Date.now(), message: `Ponte autom\xE1tica (${originLabel}): ${new Date(report.finishedAt).toLocaleString("pt-BR")}. Agenda: ${report.agenda?.accepted ? "recebida no servidor" : "envio n\xE3o confirmado"}. ${readStatus(report)} ${commandStatus(report)}`, report };
    Storage.set("bridge-auto-state", result);
    return result;
  } catch {
    const result = { state: "deferred", origin: options.origin, at: Date.now(), message: "Ponte adiada por falha ou limite de tempo. A fila ser\xE1 retomada na pr\xF3xima execu\xE7\xE3o." };
    try {
      Storage.set("bridge-auto-state", result);
    } catch {
    }
    return result;
  }
}

// scripting/scripts/Calendar Timeline Scripting/selection.ts
function localDay(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}
function parseLocalDay(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [y, m, d] = value.split("-").map(Number);
  const date = new Date(y, m - 1, d);
  return localDay(date) === value ? date : null;
}
function validateSelection(value, now = /* @__PURE__ */ new Date()) {
  const date = parseLocalDay(value);
  const { start, end } = weekRange(now);
  if (!date || date < start || date >= end) throw new Error("Data fora da semana exibida.");
  return localDay(date);
}
function weekRange(now = /* @__PURE__ */ new Date()) {
  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay());
  const end = new Date(start);
  end.setDate(end.getDate() + 7);
  return { start, end };
}

