// scripting/scripts/Calendar Timeline Scripting/app_intents.tsx
var SelectDay = AppIntentManager.register({
  name: "CalendarTimelineSelectDay",
  protocol: AppIntentProtocol.AppIntent,
  perform: async ({ date }) => {
    const now = /* @__PURE__ */ new Date();
    const selected = validateSelection(date, now);
    if (!Storage.set("selected-day", { date: selected, selectedOn: localDay(now) })) throw new Error("N\xE3o foi poss\xEDvel guardar o dia selecionado.");
    await reloadWidgets();
  }
});
var SynchronizeAgenda = AppIntentManager.register({
  name: "CalendarTimelineSynchronize",
  protocol: AppIntentProtocol.AppIntent,
  perform: async () => {
    await autoSynchronize({ origin: "control-center", force: true, budgetMS: 1e4 });
    await reloadWidgets();
  }
});

